function pick(obj, ...keys) {
    const result = {};
    for (const key of keys) {
        if (key in obj) result[key] = obj[key];
    }
    return result;
}

function omit(obj, ...keys) {
    const copy = { ...obj };
    for (const key of keys) delete copy[key];
    return copy;
}

const user = { id: 1, name: "Aziz", email: "aziz@mail.uz", password: "secret" };
